package codegen

import (
	"reflect"
	"testing"

	ir "github.com/parable-work/superschematic/ir"
)

// TestReadModelHoldsWhatAMemberMustDecode: a field is required unless it
// has a default, is @autoGenerated or is a versioned table's _version;
// each field's kind is its type's, an enum with its values, a scalar with
// its JSON kind; a nested object and an inner union, the dependency's
// included, join the model; and a union is discriminated only when every
// member gives the discriminator a value.
func TestReadModelHoldsWhatAMemberMustDecode(t *testing.T) {
	kindA, kindB := "a", "b"
	dep := &ir.Schema{
		Types: map[string]*ir.TypeDef{
			"Inner": {Name: "Inner", Fields: []*ir.FieldDef{{Name: "x", TypeRef: ir.TypeRef{Name: "number"}, Required: true}}},
		},
		Unions:  map[string]*ir.UnionDef{},
		Enums:   map[string]*ir.EnumDef{},
		Scalars: map[string]*ir.ScalarDef{},
	}
	schema := &ir.Schema{
		Scalars: map[string]*ir.ScalarDef{
			"Generic.Int64": {Name: "Generic.Int64", TypeMappings: map[string]string{"json_schema": "integer"}},
		},
		Enums: map[string]*ir.EnumDef{
			"Status": {Name: "Status", Values: []ir.EnumValueDef{{Name: "OPEN", SerializedAs: "open"}, {Name: "CLOSED"}}},
		},
		Types: map[string]*ir.TypeDef{
			"A": {Name: "A", StrictJSON: true, Fields: []*ir.FieldDef{
				{Name: "kind", TypeRef: ir.TypeRef{Name: "string"}, Required: true, InternalMetadata: true, Default: &kindA},
				{Name: "id", TypeRef: ir.TypeRef{Name: "string"}, Required: true, AutoGenerated: true},
				{Name: "_version", TypeRef: ir.TypeRef{Name: "number"}, Required: true, InternalMetadata: true},
				{Name: "status", TypeRef: ir.TypeRef{Name: "Status"}, Required: true},
				{Name: "count", TypeRef: ir.TypeRef{Name: "Generic.Int64", IsArray: true, IsArrayOfArrays: true}},
				{Name: "inner", TypeRef: ir.TypeRef{Name: "Inner", IsMap: true}},
				{Name: "next", TypeRef: ir.TypeRef{Name: "U"}},
			}},
			"B": {Name: "B", Fields: []*ir.FieldDef{
				{Name: "kind", TypeRef: ir.TypeRef{Name: "string"}, Required: true, InternalMetadata: true, Default: &kindB},
			}},
			"C": {Name: "C", Fields: []*ir.FieldDef{
				{Name: "kind", TypeRef: ir.TypeRef{Name: "string"}, Required: true, InternalMetadata: true},
			}},
		},
		Unions: map[string]*ir.UnionDef{
			"U": {Name: "U", Types: []string{"A", "B"}},
			"V": {Name: "V", Types: []string{"B", "C"}},
		},
	}
	model, err := BuildReadModel(schema, map[string]*ir.Schema{"dep": dep})
	if err != nil {
		t.Fatal(err)
	}
	if got := model.ReadModelTypeNames(); !reflect.DeepEqual(got, []string{"A", "B", "C", "Inner"}) {
		t.Fatalf("types = %v", got)
	}
	a := model.Types[0]
	want := []ReadField{
		{Name: "kind", Kind: ReadString},
		{Name: "id", Kind: ReadString},
		{Name: "_version", Kind: ReadNumber},
		{Name: "status", Required: true, Kind: ReadEnum, Values: []string{"open", "CLOSED"}},
		{Name: "count", Depth: 2, Kind: ReadScalar, Scalar: "Generic.Int64", ScalarJSON: ReadInteger},
		{Name: "inner", Map: true, Kind: ReadObject, Ref: "Inner"},
		{Name: "next", Kind: ReadUnionKind, Ref: "U"},
	}
	if !a.Strict || !reflect.DeepEqual(a.Fields, want) {
		t.Fatalf("A = %+v", a)
	}
	if u := model.Unions[model.UnionIndex("U")]; u.Discriminator != "kind" || u.Members[1].Tag != "b" {
		t.Errorf("U = %+v, want discriminated by kind", u)
	}
	if v := model.Unions[model.UnionIndex("V")]; v.IsDiscriminated() || len(v.Members[0].Fields) != 1 {
		t.Errorf("V = %+v, want picked by shape, C giving kind no value", v)
	}
}
